// Some portions generated by Claude
/**
 * Splits a connected component into its 2-core and the pendant trees hanging off it. The 2-core is what remains after
 * repeatedly removing cards with a single link; every removed card belongs to a tree attached to exactly one core card
 * (its anchor). A component that is itself a tree has an empty 2-core: its centroid (the card whose removal leaves the
 * smallest largest part) becomes the only core card, so a hub with leaves is drawn around the hub.
 */
export type Decomposition = {
  /** Core cards: the 2-core, or the root of a tree. */
  core: number[];
  /** For a pendant card, the card it hangs from (toward the core); −1 for core cards and cards outside the component. */
  parent: Int32Array;
  /** Pendant children of every card. */
  children: number[][];
  tree: boolean;
};

/**
 * `neighbors` is the simple undirected adjacency of the whole graph (no self links, no duplicates); `members` the
 * cards of one connected component; `keep` cards that must stay in the core (pinned cards).
 */
export function decomposeComponent(neighbors: readonly (readonly number[])[], members: readonly number[],
  keep: (card: number) => boolean = () => false): Decomposition {
  const n = neighbors.length;
  const inside = new Uint8Array(n);
  for (const m of members) inside[m] = 1;
  const degree = new Int32Array(n);
  for (const m of members) for (const k of neighbors[m]) if (inside[k]) degree[m]++;
  const removed = new Uint8Array(n);
  const queue: number[] = [];
  for (const m of members) if (degree[m] <= 1 && !keep(m)) { removed[m] = 1; queue.push(m); }
  for (let read = 0; read < queue.length; read++) {
    for (const k of neighbors[queue[read]]) {
      if (!inside[k] || removed[k]) continue;
      if (--degree[k] <= 1 && !keep(k)) { removed[k] = 1; queue.push(k); }
    }
  }
  let core = members.filter(m => !removed[m]);
  const tree = core.length === 0;
  if (tree) {
    const root = centroid(neighbors, members, inside);
    removed[root] = 0;
    core = [root];
  }
  const parent = new Int32Array(n).fill(-1);
  const children: number[][] = Array.from({length: n}, () => []);
  // Breadth-first from the core over removed cards gives each pendant card its unique way to the core.
  const frontier = [...core];
  const reached = new Uint8Array(n);
  for (const c of core) reached[c] = 1;
  for (let read = 0; read < frontier.length; read++) {
    const card = frontier[read];
    for (const k of neighbors[card]) {
      if (!inside[k] || reached[k] || !removed[k]) continue;
      reached[k] = 1;
      parent[k] = card;
      children[card].push(k);
      frontier.push(k);
    }
  }
  return {core, parent, children, tree};
}

/** The card whose removal leaves the smallest largest part; ties go to the higher degree, then the lower index. */
function centroid(neighbors: readonly (readonly number[])[], members: readonly number[], inside: Uint8Array) {
  if (members.length <= 2) {
    return members.reduce((best, m) => (neighbors[m].length > neighbors[best].length || (neighbors[m].length === neighbors[best].length && m < best) ? m : best), members[0]);
  }
  const root = members[0], order: number[] = [root], parent = new Map<number, number>([[root, -1]]);
  for (let read = 0; read < order.length; read++) {
    for (const k of neighbors[order[read]]) if (inside[k] && !parent.has(k)) { parent.set(k, order[read]); order.push(k); }
  }
  const size = new Map<number, number>();
  for (let i = order.length - 1; i >= 0; i--) {
    const card = order[i];
    let total = 1;
    for (const k of neighbors[card]) if (inside[k] && parent.get(k) === card) total += size.get(k)!;
    size.set(card, total);
  }
  const total = order.length;
  let best = root, bestLargest = Infinity;
  for (const card of order) {
    let largest = total - size.get(card)!;
    for (const k of neighbors[card]) if (inside[k] && parent.get(k) === card) largest = Math.max(largest, size.get(k)!);
    const better = largest < bestLargest ||
      (largest === bestLargest && (neighbors[card].length > neighbors[best].length || (neighbors[card].length === neighbors[best].length && card < best)));
    if (better) { best = card; bestLargest = largest; }
  }
  return best;
}

/** Connected components (by the simple adjacency) as lists of card indices, in order of their first card. */
export function componentsOf(neighbors: readonly (readonly number[])[]) {
  const n = neighbors.length, owner = new Int32Array(n).fill(-1), components: number[][] = [];
  for (let seed = 0; seed < n; seed++) {
    if (owner[seed] >= 0) continue;
    const members = [seed];
    owner[seed] = components.length;
    for (let read = 0; read < members.length; read++) {
      for (const k of neighbors[members[read]]) if (owner[k] < 0) { owner[k] = components.length; members.push(k); }
    }
    components.push(members);
  }
  return components;
}
